use mbrotli::{Compressor, EncoderConfig, Quality, InputSize, StreamConfig};
use std::{hint::black_box, time::{Duration, Instant}, io::Write};
fn corpus(name: &str) -> Vec<u8> {
    let text = include_bytes!("../../../../brotli-ffi/vendor/brotli/tests/testdata/alice29.txt");
    match name {
        "empty" => Vec::new(),
        "tiny-text" => b"The quick brown fox jumps over the lazy dog.".to_vec(),
        "alice29" => text.to_vec(),
        "text-1m" => text.iter().copied().cycle().take(1_048_576).collect(),
        "repeated-1m" => vec![b'a'; 1_048_576],
        "binary-64k" => (0..65_536_u32).map(|i| ((i / 16) ^ i) as u8).collect(),
        "random-64k" | "random-1m" => {
            let size = if name == "random-64k" {65_536} else {1_048_576};
            let mut state=0x243f_6a88_85a3_08d3_u64;
            (0..size).map(|_| {state ^= state << 13; state ^= state >> 7; state ^= state << 17; state as u8}).collect()
        }
        path => std::fs::read(path).unwrap(),
    }
}
#[cfg_attr(feature="hotpath", hotpath::main)]
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    let qualities:Vec<u8> = if args[1]=="all" {(0..=11).collect()} else {vec![args[1].parse()?]};
    let names:Vec<&str> = if args[2]=="all" {vec!["empty", "tiny-text", "alice29", "text-1m", "binary-64k", "random-64k", "random-1m", "repeated-1m"]} else {vec![&args[2]]};
    let seconds:f64 = args.get(4).map(|x| x.parse()).transpose()?.unwrap_or(0.15);
    for name in names {
        let input=corpus(name);
        for &q in &qualities {
            let config=EncoderConfig::default().with_quality(Quality::try_from(q)?);
            let mut owner=Compressor::new(config)?;
            let mut output=Vec::with_capacity(Compressor::max_compressed_size(input.len())?);
            let expected=owner.compress(&input)?;
            let checksum = expected.iter().fold(0xcbf29ce484222325u64, |h, &b| (h ^ u64::from(b)).wrapping_mul(0x100000001b3));
            let start=Instant::now();
            let mut iterations=0u64;
            loop {
                match args[3].as_str() {
                    "cold" => { let actual=Compressor::new(config)?.compress(black_box(&input))?; black_box(actual); }
                    "reused" => { output.clear(); owner.compress_into(black_box(&input), &mut output)?; black_box(&output); }
                    "writer" => {
                        output.clear();
                        let stream = StreamConfig::default().with_input_size(InputSize::Exact(input.len() as u64));
                        let mut writer=owner.writer(&mut output, stream)?;
                        for chunk in input.chunks(4096) {writer.write_all(black_box(chunk))?;}
                        writer.finish().map_err(|e| e.to_string())?;
                        black_box(&output);
                    }
                    _ => return Err("unknown mode".into()),
                }
                iterations+=1;
                if start.elapsed() >= Duration::from_secs_f64(seconds) {break;}
            }
            println!("{name},{q},{},{},{},{},{:.3}",args[3],input.len(),expected.len(),checksum,start.elapsed().as_nanos() as f64 / iterations as f64);
        }
    }
    Ok(())
}

