fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args:Vec<_>=std::env::args().collect();
    let pairs:usize=args.get(1).map(|s|s.parse()).transpose()?.unwrap_or(10);
    let budget:f64=args.get(2).map(|s|s.parse()).transpose()?.unwrap_or(0.03);
    let mode=args.get(3).map(String::as_str).unwrap_or("cold");
    let qfilter=args.get(4).map(String::as_str).unwrap_or("all");
    let cfilter=args.get(5).map(String::as_str).unwrap_or("all");
    println!("corpus,quality,mode,input_bytes,compressed_bytes,pair,order,iterations,before_ns,after_ns,retained_before,retained_after");
    for name in ["empty","tiny-text","alice29","text-1m","binary-64k","random-64k","random-1m","repeated-1m"] {
        if cfilter!="all" && !cfilter.split(',').any(|x|x==name) {continue;}
        let input=corpus(name);
        for q in 0..=11 {
            if qfilter!="all" && !qfilter.split(',').any(|s|s.parse::<u8>().unwrap()==q) {continue;}
            macro_rules! config {($lib:ident) => {$lib::EncoderConfig::default().with_quality($lib::Quality::try_from(q)?)};}
            let old_config=config!(mbrotli_before); let new_config=config!(mbrotli);
            let mut old_owner=mbrotli_before::Compressor::new(old_config)?;
            let mut new_owner=mbrotli::Compressor::new(new_config)?;
            let expected=old_owner.compress(&input)?;
            assert_eq!(expected,new_owner.compress(&input)?,"{name} q{q}");
            let mut old_output=Vec::with_capacity(mbrotli_before::Compressor::max_compressed_size(input.len())?);
            let mut new_output=Vec::with_capacity(mbrotli::Compressor::max_compressed_size(input.len())?);
            macro_rules! runner {($lib:ident,$config:ident,$owner:ident,$out:ident) => {|| {
                match mode {
                    "cold" => {black_box($lib::Compressor::new($config).unwrap().compress(black_box(&input)).unwrap());}
                    "reused" => {$out.clear();$owner.compress_into(black_box(&input), &mut $out).unwrap();black_box(&$out);}
                    "writer" => {
                        $out.clear();
                        let stream=$lib::StreamConfig::default().with_input_size($lib::InputSize::Exact(input.len() as u64));
                        let mut writer=$owner.writer(&mut $out,stream).unwrap();
                        for c in input.chunks(4096) {writer.write_all(black_box(c)).unwrap();}
                        writer.finish().unwrap();black_box(&$out);
                    }
                    _ => panic!("mode"),
                }
            }};}
            // Validate the actual API mode before the timing closures borrow it.
            runner!(mbrotli_before,old_config,old_owner,old_output)();
            runner!(mbrotli,new_config,new_owner,new_output)();
            if mode != "cold" {
                assert_eq!(old_output, expected, "baseline {name} q{q} {mode}");
                assert_eq!(new_output, expected, "candidate {name} q{q} {mode}");
            }
            let old_retained=old_owner.retained_bytes();let new_retained=new_owner.retained_bytes();
            let mut old_run=runner!(mbrotli_before,old_config,old_owner,old_output);
            let mut new_run=runner!(mbrotli,new_config,new_owner,new_output);
            let estimate=timed(&mut old_run,2).max(timed(&mut new_run,2));
            let count=(budget*1e9/estimate).max(1.0).min(10_000_000.0) as usize;
            timed(&mut old_run,count);timed(&mut new_run,count);
            for pair in 0..pairs {
                let (old,new)=if pair%4==0 || pair%4==3 {
                    let old=timed(&mut old_run,count);let new=timed(&mut new_run,count);(old,new)
                } else {
                    let new=timed(&mut new_run,count);let old=timed(&mut old_run,count);(old,new)
                };
                println!("{name},{q},{mode},{},{},{pair},{},{count},{old:.3},{new:.3},{old_retained},{new_retained}",input.len(),expected.len(),if pair%4==0 || pair%4==3 {"AB"} else {"BA"});
            }
            std::io::stdout().flush()?;
        }
    }
    Ok(())
}

