from pathlib import Path
from collections import defaultdict
import csv,json,statistics,random,hashlib,re
root=Path(__file__).resolve().parents[2];out=root/'target/encoder-optimization';pub=root/'docs/benchmarks/encoder-optimization-2026-09-14'
def read(name):
    with (pub/name).open() as source: return list(csv.DictReader(source))
def write(name,rows):
    assert rows
    with (pub/name).open('w') as dest:
        writer=csv.DictWriter(dest,fieldnames=list(rows[0]),lineterminator='\n');writer.writeheader();writer.writerows(rows)
# Paired rows are the sampling unit; preserve the before/after pairing.
rng=random.Random(197);summary=[]
for filename,expected in [('paired-cold.csv',96),('paired-reused.csv',96),('paired-writer.csv',96),('paired-heldout.csv',42)]:
    groups=defaultdict(list)
    for row in read(filename): groups[(row['corpus'],int(row['quality']),row['mode'])].append(row)
    assert len(groups)==expected
    for (corpus,quality,mode),rows in sorted(groups.items()):
        count=12 if filename=='paired-heldout.csv' else 16
        assert len(rows)==count and len({int(x['pair']) for x in rows})==count
        ratios=[float(x['before_ns'])/float(x['after_ns']) for x in rows]
        draws=sorted(statistics.geometric_mean(rng.choices(ratios,k=count)) for _ in range(2000))
        first=rows[0]
        summary.append({'suite':'heldout' if filename=='paired-heldout.csv' else 'primary','corpus':corpus,'quality':quality,'mode':mode,'input_bytes':int(first['input_bytes']),'compressed_bytes':int(first['compressed_bytes']),'pairs':count,'before_ns':statistics.mean(float(x['before_ns']) for x in rows),'after_ns':statistics.mean(float(x['after_ns']) for x in rows),'speedup':statistics.geometric_mean(ratios),'speedup_lower':draws[50],'speedup_upper':draws[1949],'retained_before':int(first['retained_before']),'retained_after':int(first['retained_after']),'retained_delta':int(first['retained_after'])-int(first['retained_before'])})
write('paired-summary.csv',summary)
# Keep native-API competitor rankings distinct from the causal paired trials.
versions={}
for version in ['before','after']:
    rows=read('comparison-'+version+'.csv');assert len(rows)==432
    cases=defaultdict(list)
    for row in rows: cases[(row['corpus'],int(row['quality']))].append(row)
    versions[version]=cases
ranked=[]
for q in range(12):
    result={'quality':q,'cases':8}
    for version,cases in versions.items():
        wins=clear=0;vs_c=[]
        for (corpus,quality),rows in cases.items():
            if quality!=q: continue
            mb=next(x for x in rows if x['implementation']=='mbrotli')
            others=[x for x in rows if x['implementation']!='mbrotli']
            wins+=all(float(mb['mean_ns'])<float(x['mean_ns']) for x in others)
            clear+=all(float(mb['mean_upper_ns'])<float(x['mean_lower_ns']) for x in others)
            vs_c.append(float(mb['speed_relative_to_c']))
        result[version+'_lowest_mean']=wins;result[version+'_disjoint_intervals']=clear
        result[version+'_median_speed_relative_to_c']=statistics.median(vs_c)
    ranked.append(result)
write('competitor-summary.csv',ranked)
for key in versions['before']:
    old={r['implementation']:r['compressed_bytes'] for r in versions['before'][key]}
    new={r['implementation']:r['compressed_bytes'] for r in versions['after'][key]}
    assert old==new,(key,old,new)
# Final profile totals are diagnostic inclusive timing or exclusive requested bytes.
profiles=[]
for q in range(12):
    for kind,filename,section in [('timing',f'cpu-final-q{q}-all.json','functions_timing'),('allocated-bytes',f'alloc-final-q{q}.json','functions_alloc')]:
        data=json.loads((out/filename).read_text())
        if section not in data:
            section=next(k for k in data if k.startswith('functions_alloc'))
        for row in data[section]['data']:
            profiles.append({'quality':q,'mode':kind,'function':row['name'],'calls':row['calls'],'average':row.get('avg',''),'total':row.get('total',''),'percent_total':row.get('percent_total','')})
write('profiles-after.csv',profiles)
# Root Criterion comparisons include matching C streaming FINISH semantics.
sizes={}
for line in (out/'criterion-root-final.log').read_text().splitlines():
    m=re.match(r'q(\d+)\s+(\S+)\s+c-brotli\s+(\d+) bytes\s+mbrotli\s+(\d+) bytes',line)
    if m: sizes[(int(m[1]),m[2])]=(int(m[3]),int(m[4]))
rows=[]
for path in (root/'target/criterion').rglob('encoder-final-20260914/benchmark.json'):
    meta=json.loads(path.read_text());mean=json.loads((path.parent/'estimates.json').read_text())['mean']
    name=meta['full_id'];parts=name.split('/');q=int(parts[1][1:]);corpus=parts[-1]
    input_bytes=meta['throughput']['Bytes'];size=sizes.get((q,corpus),('',''))[0 if parts[2]=='c-brotli' else 1]
    rows.append({'case':name,'input_bytes':input_bytes,'compressed_bytes':size,'mean_ns':mean['point_estimate'],'lower_ns':mean['confidence_interval']['lower_bound'],'upper_ns':mean['confidence_interval']['upper_bound'],'mib_per_second':input_bytes*1e9/mean['point_estimate']/1048576})
assert len(rows)==16,len(rows);write('root-criterion.csv',sorted(rows,key=lambda x:x['case']))
print('Published',len(summary),'paired cases;',sum(x['after_lowest_mean'] for x in ranked),'/ 96 lowest native means;',sum(x['after_disjoint_intervals'] for x in ranked),'disjoint native leads')

